# ================================================================ part 2: the case, slowly
opener(2, 'סיפור מקרה: נועה בבנק', 'שאלת החלק: למה מספר אחד מהדוחות לא מספיק כדי להחליט?',
       ['נועה מבקשת הלוואה לסניף שני', 'הבנקאית: ״מספר לבד לא אומר לי כלום״', 'רווח נקי של 123,200: שלוש השוואות, שלושה כלים'], 10, art=('bank', 'נועה הולכת לבנק'))

def _line(n, who, side, text, toon):
    if MODE == 'pdf':
        return f'<p><b>{who}:</b> {TX(text)}</p>'
    return ST(n, f'<div class="dl {side}"><div class="dav">{_svg(TOONS[toon])}</div><div class="dbub"><span class="dwho">{who}</span>{TX(text)}</div></div>')


S('c-dlg', 'נועה בבנק', 'נועה בבנק',
  '<div class="dlg">'
  + _line(1, 'נועה', 'r', 'אני רוצה לפתוח סניף שני של קפה נועה. הוא יעלה 150,000 ש״ח. אפשר לקבל הלוואה?', 'barista')
  + _line(2, 'הבנקאית', 'l', 'אשמח לראות את הדוחות הכספיים שלך. של 2027, וגם של 2026.', 'banker')
  + _line(3, 'נועה', 'r', 'גם של 2026? למה? ב-2027 הרווח הנקי שלי היה 123,200 ש״ח!', 'barista')
  + _line(4, 'הבנקאית', 'l', 'ו-123,200 זה הרבה או מעט? מספר אחד לבד לא אומר לי כלום. אני צריכה להשוות אותו למשהו.', 'banker')
  + '</div>', kick='חלק 2 · סיפור מקרה')

