_IS2 = {n: (a, b) for n, a, b in _IS}
_HR = [x for x in _IS if x[0] in ('מכירות', 'עלות המכירות', 'רווח גולמי', 'הוצאות הנהלה וכלליות', 'רווח תפעולי', 'רווח נקי')]

# ---------------------------------------------------------------- 1. horizontal analysis: the example, click by click
_hrows = ''
for _i, (_n, _a, _b) in enumerate(_HR):
    _d = _b - _a; _p = _d / _a
    _hrows += (f'<tr class="{"tot" if _n.startswith("רווח") else ""}"><td>{TX(_n)}</td><td class="c"><span class="n">{_a:,}</span></td><td class="c"><span class="n">{_b:,}</span></td>'
               f'<td class="c">{_calc(2 * _i + 1, _sg(_d), f"{_n}: השינוי בשקלים", [f"השנה פחות השנה הקודמת: {_b:,} פחות {_a:,}.", f"התוצאה: {_sg(_d)} ש״ח."], "up")}</td>'
               f'<td class="c">{_calc(2 * _i + 2, _sg(_p, True), f"{_n}: השינוי באחוזים", [f"השינוי בשקלים חלקי השנה הקודמת, שהיא הבסיס: {_d:,} חלקי {_a:,}.", f"התוצאה: {_p:.3f}, כלומר {_sg(_p, True)}.", "תמיד מחלקים בשנה הקודמת: שואלים בכמה גדלנו ביחס למה שהיה."], "up")}</td></tr>')
S('s-an-hor', 'ניתוח אופקי: הכול יחד', 'ועכשיו הכול יחד: ניתוח אופקי של דוח רווח והפסד',
  '<div class="anrow"><div class="col"><table class="tbl2 stmt hor anx"><tr><th>קפה נועה, רווח והפסד</th><th>2026</th><th>2027</th><th>שינוי בש״ח</th><th>שינוי ב-%</th></tr>' + _hrows + '</table>'
  + '<p class="fhint">' + TX('בכל לחיצה נחשף מספר אחד: קודם השינוי בשקלים, אחר כך באחוזים. לחצו על מספר כדי לראות איך חושב.') + '</p></div>'
  + '<div class="col">' + DEF('ניתוח אופקי (Horizontal analysis)', 'משווים כל שורה בדוח לאותה שורה בשנה הקודמת: בכמה שקלים, ובכמה אחוזים, היא השתנתה.', 'מכירות: 600,000 מול 504,000. גידול של 96,000, ו-96,000 חלקי 504,000 הם 19%.', n=13, trm='horiz')
  + '</div></div>', kick='חלק 5 · מהדוגמה לכלל')

_HL = [x for x in _IS if x[0] in ('מכירות', 'עלות המכירות', 'רווח גולמי', 'רווח תפעולי', 'רווח נקי')]
QT('x-an-hor', 'ניתוח אופקי', 'השינוי משנה לשנה, בגיליון', ['לכל שורה: בעמודה D השינוי בשקלים, ובעמודה E השינוי באחוזים. הבסיס הוא תמיד השנה הקודמת, 2026.'],
   'השינוי בשקלים: 2027 פחות 2026. השינוי באחוזים: השינוי חלקי 2026.',
   _bigsheet(['שורה בדוח', 'שנת 2026', 'שנת 2027', 'שינוי בש״ח', 'שינוי ב-%'], _HL, [('D', '=C{r}-B{r}', 'acc0'), ('E', '=D{r}/B{r}', 'pct1')], [190, 125, 125, 135, 125],
             None, lambda i, r: f'<b>{r[0]}:</b> {XL(f"=C{2 + i}-B{2 + i}")} הוא השינוי בשקלים, {_sg(r[2] - r[1])}; {XL(f"=D{2 + i}/B{2 + i}")} הוא השינוי ביחס ל-2026, {_sg((r[2] - r[1]) / r[1], True)}.'),
   one=True, big=True, hints=['שינוי בשקלים: =C2-B2. שינוי באחוזים: =D2/B2. אחר כך גוררים למטה.'], remind='=D2/B2', done='המכירות גדלו ב-19.0%, והרווח הנקי ב-33.3%.')

# the results of the horizontal analysis, beside five questions from easy to hard
_HRES = [(n, f'{a:,}', f'{b:,}', _sg(b - a), _sg((b - a) / a, True)) for n, a, b in _HR]
_hside = lambda hl=None: _dt(['שורה', '2026', '2027', 'שינוי בש״ח', 'שינוי ב-%'], _HRES, hl, 'mdt')
