for _i, (_n, _a, _b) in enumerate(_VR):
    _vrows += (f'<tr class="{"tot" if _n.startswith("רווח") else ""}"><td>{TX(_n)}</td><td class="c"><span class="n">{_a:,}</span></td>'
               f'<td class="c">{_calc(2 * _i + 1, _pc(_a / 504000), f"{_n} כאחוז מהמכירות, 2026", [f"השורה חלקי המכירות של אותה שנה: {_a:,} חלקי 504,000.", f"התוצאה: {_a / 504000:.3f}, כלומר {_pc(_a / 504000)}. מכל 100 ש״ח של מכירות: {_a / 5040:.1f} ש״ח."], "up")}</td>'
               f'<td class="c"><span class="n">{_b:,}</span></td>'
               f'<td class="c">{_calc(2 * _i + 2, _pc(_b / 600000), f"{_n} כאחוז מהמכירות, 2027", [f"השורה חלקי המכירות של אותה שנה: {_b:,} חלקי 600,000.", f"התוצאה: {_b / 600000:.3f}, כלומר {_pc(_b / 600000)}. מכל 100 ש״ח של מכירות: {_b / 6000:.1f} ש״ח."], "up")}</td></tr>')
S('s-an-ver', 'ניתוח אנכי: הכול יחד', 'ועכשיו הכול יחד: ניתוח אנכי של דוח רווח והפסד',
  '<div class="anrow"><div class="col"><table class="tbl2 stmt hor anx"><tr><th>קפה נועה, רווח והפסד</th><th>2026</th><th>% מהמכירות</th><th>2027</th><th>% מהמכירות</th></tr>' + _vrows + '</table>'
  + '<p class="fhint">' + TX('בכל לחיצה נחשף אחוז אחד. לחצו עליו כדי לראות איך חושב.') + '</p></div>'
  + '<div class="col">' + DEF('ניתוח אנכי (Vertical analysis)', 'כל שורה בדוח כאחוז משורת בסיס: בדוח רווח והפסד הבסיס הוא המכירות, ובמאזן, סך הנכסים.', 'רווח נקי 123,200 מתוך מכירות 600,000: 20.5 שקלים מכל 100.', n=11, trm='vert')
  + DEF('שיעור רווח (Profit margin)', 'רווח חלקי המכירות. יש שיעור רווח גולמי, שיעור רווח תפעולי ושיעור רווח נקי.', 'שיעור הרווח הנקי עלה מ-18.3% ב-2026 ל-20.5% ב-2027.', n=12, trm='margin') + '</div></div>', kick='חלק 5 · מהדוגמה לכלל')

