def _ratrows(d, g, f, st, sol, steps):
    d['A7'] = 'יחס'; d['B7'] = 'שנת 2026'; d['C7'] = 'שנת 2027'; d['D7'] = 'איך מחשבים'
    for c in 'ABCD': st[f'{c}7'] = {'fill': '#fff0c2', 'b': True, 'al': 'center' if c in 'BC' else 'right'}
    for i, (n, fx, fm, how) in enumerate(_RT):
        r = 8 + i; d[f'A{r}'] = n; d[f'D{r}'] = how
        cells = {}
        for c in 'BC':
            sol[f'{c}{r}'] = fx.format(c=c); f[f'{c}{r}'] = fm; st[f'{c}{r}'] = {'al': 'center'}; cells[f'{c}{r}'] = sol[f'{c}{r}']
        steps.append(dict(cells=cells, note=f'<b>{n}:</b> {how}: {XL(fx.format(c="B"))} ל-2026, וכך גם ל-2027.', sel=f'B{r}'))


